// Sample payload so the template can be tested with the Manual Trigger,
// without wiring up a parent workflow first. Delete this node once you
// are calling the sub-workflow for real.

return {
  json: {
    approvalTitle: 'Send onboarding email to Example Ltd',
    approvalSummary:
      'Subject: Welcome aboard!\n\n' +
      'Hi there,\n\nYour account is ready. Book your kickoff call here: ' +
      'https://example.com/booking\n\nThanks,\nThe team',
    referenceId: 'DEMO-001',
    requestedBy: 'Onboarding workflow (demo run)',
  },
};

// Builds the ClickUp task that a human will act on.
// Nothing in here is app-specific — it renders whatever the caller passed in.

const req = $input.item.json;
const cfg = $('Approval Settings').first().json;

const titlePrefix = cfg.taskTitlePrefix || '';
const taskName = (titlePrefix ? titlePrefix + ' ' : '') + req.approvalTitle;

const executionLink = cfg.n8nInstanceUrl && !cfg.n8nInstanceUrl.includes('YOUR_N8N_INSTANCE_URL')
  ? cfg.n8nInstanceUrl.replace(/\/+$/, '') + '/workflow/' + $workflow.id + '/executions/' + $execution.id
  : null;

// ClickUp task descriptions render Markdown, not HTML. If the caller passes
// HTML in approvalSummary it will show as raw tags, so strip the common ones.
const summary = String(req.approvalSummary || '')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/p>/gi, '\n\n')
  .replace(/<[^>]+>/g, '')
  .trim();

const lines = [
  '**Action required:** review the item below, then set this task\'s status to one of:',
  '',
  '- `' + cfg.statusApproved + '` — approve and let the automation continue',
  '- `' + cfg.statusRevision + '` — send it back for changes (leave a comment saying what to change)',
  '- `' + cfg.statusRejected + '` — reject outright (leave a comment saying why)',
  '',
  '---',
  '',
];

if (req.referenceId)  lines.push('**Reference:** ' + req.referenceId);
if (req.requestedBy)  lines.push('**Requested by:** ' + req.requestedBy);
lines.push('**Raised:** ' + new Date().toISOString());
lines.push('');
lines.push('---');
lines.push('');
lines.push(summary || '_No summary was supplied by the calling workflow._');

if (executionLink) {
  lines.push('');
  lines.push('---');
  lines.push('');
  lines.push('[Open the n8n execution](' + executionLink + ')');
}

const payload = {
  name: taskName,
  description: lines.join('\n'),
  notify_all: true,
};

if (cfg.assigneeUserId && !String(cfg.assigneeUserId).startsWith('PASTE_')) {
  payload.assignees = [Number(cfg.assigneeUserId)];
}
if (cfg.taskPriority) {
  payload.priority = Number(cfg.taskPriority);
}
// Give the reviewer a visible deadline that matches the workflow's own timeout.
const slaMs = Number(cfg.pollIntervalMinutes) * Number(cfg.maxPollAttempts) * 60 * 1000;
if (slaMs > 0) {
  payload.due_date = Date.now() + slaMs;
  payload.due_date_time = true;
}

return { json: { ...req, taskName, taskPayload: payload } };

// Turns the created task into a short channel message.

const task = $input.item.json;              // ClickUp create-task response
const prior = $('Build Approval Task').item.json;
const cfg = $('Approval Settings').first().json;

const taskUrl = task.url || 'https://app.clickup.com/t/' + task.id;

const message = [
  ':memo: **Approval needed:** ' + prior.approvalTitle,
  taskUrl,
  '',
  'Set the task status to `' + cfg.statusApproved + '`, `' + cfg.statusRevision +
    '` or `' + cfg.statusRejected + '` to unblock the automation.',
].join('\n');

return { json: { ...prior, taskId: task.id, taskUrl, channelMessage: message } };

// Reads the polled task and decides which branch the workflow takes.
// $runIndex counts how many times this node has run in this execution,
// which is exactly the number of completed poll cycles.

const task = $input.item.json;
const cfg = $('Approval Settings').first().json;

const attempt = $runIndex + 1;
const maxAttempts = Number(cfg.maxPollAttempts) || 96;
const remindAfter = Number(cfg.reminderAfterAttempts) || 0;

const norm = (v) => String(v ?? '').trim().toLowerCase();

// ClickUp lowercases status names in API responses, but users type them into
// Approval Settings however they like — so normalise both sides.
const current = norm(task?.status?.status);
const approved = norm(cfg.statusApproved);
const revision = norm(cfg.statusRevision);
const rejected = norm(cfg.statusRejected);

let decision;
if (!current)                 decision = 'pending';   // task unreadable this cycle; try again
else if (current === approved) decision = 'approved';
else if (current === revision) decision = 'revision';
else if (current === rejected) decision = 'rejected';
else if (attempt >= maxAttempts) decision = 'timeout';
else decision = 'pending';

// A reminder is due exactly once, on the cycle that crosses the threshold.
const reminderDue = decision === 'pending' && remindAfter > 0 && attempt === remindAfter;

// Best-effort: ClickUp's public v2 API does not expose status-change history,
// so the assignee is the closest available stand-in for "who decided".
const assignee = Array.isArray(task?.assignees) && task.assignees.length
  ? (task.assignees[0].username || task.assignees[0].email || null)
  : null;

return {
  json: {
    decision,
    reminderDue,
    attempt,
    maxAttempts,
    waitedMinutes: attempt * (Number(cfg.pollIntervalMinutes) || 0),
    observedStatus: task?.status?.status || null,
    assignee,
    taskId: $('Create Approval Task').first().json.id,
    taskUrl: $('Build Notification Message').first().json.taskUrl,
  },
};

// Pulls the newest reviewer comment so the caller gets actionable feedback
// rather than just a verdict.

const comments = $input.item.json?.comments || [];

// ClickUp returns comments newest-first, but don't rely on it — sort by date.
const sorted = [...comments].sort((a, b) => Number(b.date || 0) - Number(a.date || 0));
const latest = sorted[0] || null;

const text = latest
  ? (latest.comment_text || (latest.comment || []).map(c => c.text || '').join('')).trim()
  : '';

return {
  json: {
    reviewerNotes: text || null,
    decidedBy: latest?.user?.username || latest?.user?.email || null,
    decidedAt: latest?.date ? new Date(Number(latest.date)).toISOString() : null,
    commentCount: comments.length,
  },
};

